examples.template:
VStack(alignment: .leading, spacing: 12) {
    MonarchMarketingConsentCheckbox(
        selection: $channels,
        description: {{description}},
        policyTitle: {{policy.label}},
        policyURL: URL(string: {{policy.href}})
    )
